namespace sv_005daf8e966643aa80a44295fbf21613.Services;

/// <summary>
/// In-memory stub implementation of IChatService for development/demo purposes.
/// </summary>
public class StubChatService : IChatService
{
    private readonly List<Channel> _channels;
    private readonly List<Message> _messages;
    private int _nextMessageId;

    public StubChatService()
    {
        _channels = new()
        {
            new(1, "general", "General discussion for the team", 3),
            new(2, "engineering", "Engineering topics and code reviews", 0),
            new(3, "design", "Design discussions and assets", 1),
            new(4, "random", "Off-topic and fun stuff", 5),
            new(5, "announcements", "Important team announcements", 0),
        };

        var now = DateTime.UtcNow;
        _messages = new()
        {
            new(1, 1, "Alice", "Hey team! Welcome to the new chat app.", now.AddHours(-5), null,
                new() { new("👍", new() { "Bob", "Carol" }), new("🎉", new() { "Dave" }) }),
            new(2, 1, "Bob", "Looks great! Really loving the new design.", now.AddHours(-4.5), null,
                new() { new("❤️", new() { "Alice" }) }),
            new(3, 1, "Carol", "Thanks Alice! Quick question about the deployment schedule.", now.AddHours(-4), null, new()),
            new(4, 1, "Alice", "We're targeting Friday for the release.", now.AddHours(-3.8), 3, new()),
            new(5, 1, "Dave", "Friday works for me. I'll have the docs ready by then.", now.AddHours(-3.5), 3, new()),
            new(6, 1, "Carol", "Perfect, thanks everyone!", now.AddHours(-3), 3, new()),
            new(7, 1, "Bob", "Don't forget to update the changelog before release.", now.AddHours(-2), null,
                new() { new("👀", new() { "Alice", "Carol" }) }),
            new(8, 1, "Dave", "Has anyone tested the new API endpoints?", now.AddHours(-1), null, new()),
            new(9, 1, "Alice", "Yes, all passing. CI is green.", now.AddHours(-0.5), 8, new()),
            new(10, 1, "Bob", "I just pushed a fix for the login issue.", now.AddMinutes(-15), null,
                new() { new("🚀", new() { "Alice", "Carol", "Dave" }) }),
            new(11, 1, "Carol", "Nice work Bob! That's been bugging me all week.", now.AddMinutes(-10), null, new()),
            new(12, 1, "Dave", "Standup in 5 minutes everyone.", now.AddMinutes(-2), null, new()),

            new(20, 2, "Alice", "PR #142 is ready for review — refactored the auth module.", now.AddHours(-6), null,
                new() { new("👀", new() { "Bob" }) }),
            new(21, 2, "Bob", "I'll take a look this afternoon.", now.AddHours(-5), null, new()),
            new(22, 2, "Carol", "We should consider switching to the new ORM. Thoughts?", now.AddHours(-3), null, new()),
            new(23, 2, "Dave", "I've used it before — much better query performance.", now.AddHours(-2.5), 22, new()),
            new(24, 2, "Alice", "Let's spike it next sprint.", now.AddHours(-2), 22, new()),

            new(30, 3, "Carol", "New mockups are in Figma, link in the thread.", now.AddHours(-8), null, new()),
            new(31, 3, "Dave", "The color palette looks amazing.", now.AddHours(-7), null,
                new() { new("🎨", new() { "Carol" }) }),

            new(40, 4, "Bob", "Anyone up for lunch today?", now.AddHours(-3), null, new()),
            new(41, 4, "Dave", "Sure, how about tacos?", now.AddHours(-2.8), 40, new()),
            new(42, 4, "Alice", "Count me in!", now.AddHours(-2.5), 40, new()),
            new(43, 4, "Carol", "Check out this hilarious meme I found.", now.AddMinutes(-30), null,
                new() { new("😂", new() { "Bob", "Dave", "Alice" }) }),
        };

        _nextMessageId = _messages.Max(m => m.Id) + 1;
    }

    public Task<List<Channel>> GetChannelsAsync()
    {
        return Task.FromResult(_channels.Select(c => c with { }).ToList());
    }

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        // Return only root messages (ReplyToId == null) for the channel feed
        var messages = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();

        return Task.FromResult(messages);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var msg = new Message(
            _nextMessageId++,
            channelId,
            "You",
            content,
            DateTime.UtcNow,
            replyToId,
            new List<Reaction>()
        );
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var root = _messages.FirstOrDefault(m => m.Id == rootMessageId);
        if (root == null)
            return Task.FromResult(new List<Message>());

        var replies = _messages
            .Where(m => m.ReplyToId == rootMessageId)
            .OrderBy(m => m.SentAt)
            .ToList();

        var thread = new List<Message> { root };
        thread.AddRange(replies);
        return Task.FromResult(thread);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var idx = _messages.FindIndex(m => m.Id == messageId);
        if (idx < 0) return Task.CompletedTask;

        var msg = _messages[idx];
        var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
        if (existing != null)
        {
            if (!existing.Users.Contains("You"))
                existing.Users.Add("You");
        }
        else
        {
            msg.Reactions.Add(new Reaction(emoji, new List<string> { "You" }));
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        return Task.CompletedTask;
    }
}

