            <h3>💬 Channels</h3>
        </div>
        <ul class="channel-list">
            @if (_channels is not null)
            {
                @foreach (var channel in _channels)
                {
                    <li class="channel-item @(channel.Id == _activeChannelId ? "active" : "")"
                        @onclick="() => SelectChannelAsync(channel.Id)">
                        <div class="channel-info">
                            <span class="channel-name"># @channel.Name</span>
                            <span class="channel-desc">@TruncateDescription(channel.Description)</span>
                        </div>
                        @if (channel.UnreadCount > 0)
                        {
                            <span class="unread-badge">@channel.UnreadCount</span>
                        }
                    </li>
                }
            }
        </ul>
    </aside>

    @* ─── MAIN MESSAGE AREA ─── *@
    <section class="message-area @(_threadOpen ? "" : "expanded")">
        @if (_activeChannel is not null)
        {
            <div class="message-header">
                <h2># @_activeChannel.Name</h2>
                <span class="header-desc">@_activeChannel.Description</span>
            </div>

            <div class="message-list" @onscroll="OnMessageListScroll" @ref="_messageListRef">
                @if (_loadingOlder)
                {
                    <div class="loading-indicator">Loading older messages…</div>
                }
                @if (_messages is not null)
                {
                    @foreach (var msg in _messages)
                    {
                        <div class="message-row" @onmouseenter="() => _hoveredMessageId = msg.Id"
                             @onmouseleave="() => _hoveredMessageId = null">
                            <div class="message-bubble">
                                <div class="message-meta">
                                    <span class="msg-author">@msg.Author</span>
                                    <span class="msg-time">@FormatRelativeTime(msg.SentAt)</span>
                                </div>
                                <div class="msg-content">@msg.Content</div>

                                @if (msg.Reactions.Count > 0)
                                {
                                    <div class="reaction-row">
                                        @foreach (var r in msg.Reactions)
                                        {
                                            <span class="reaction-badge"
                                                  title="@string.Join(", ", r.Users)"
                                                  @onclick="() => ReactAsync(msg.Id, r.Emoji)">
                                                @r.Emoji @r.Users.Count
                                            </span>
                                        }
                                    </div>
                                }

                                @{ var replyCount = GetReplyCount(msg.Id); }
                                @if (replyCount > 0)
                                {
                                    <button class="thread-link" @onclick="() => OpenThreadAsync(msg.Id)">
                                        💬 @replyCount @(replyCount == 1 ? "reply" : "replies")
                                    </button>
                                }
                            </div>

                            @if (_hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" title="Reply in thread"
                                            @onclick="() => OpenThreadAsync(msg.Id)">
                                        💬
                                    </button>
                                    <button class="action-btn" title="Add reaction"
                                            @onclick="() => ToggleEmojiPicker(msg.Id)">
                                        😀
                                    </button>
                                </div>

                                @if (_emojiPickerMessageId == msg.Id)
                                {
                                    <div class="emoji-picker">
                                        @foreach (var emoji in _commonEmojis)
                                        {
                                            <button class="emoji-option"
                                                    @onclick="() => ReactAsync(msg.Id, emoji)">
                                                @emoji
                                            </button>
                                        }
                                    </div>
                                }
                            }
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Type a message…"
                          @bind="_newMessageText" @bind:event="oninput"
                          @onkeydown="OnMessageKeyDown" />
                <button class="send-btn" @onclick="SendMessageAsync"
                        disabled="@string.IsNullOrWhiteSpace(_newMessageText)">
                    Send
                </button>
            </div>
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </section>

    @* ─── RIGHT THREAD PANEL ─── *@
    @if (_threadOpen)
    {
        <aside class="thread-panel">
            <div class="thread-header">
                <h3>Thread</h3>
                <button class="close-thread-btn" @onclick="CloseThread">✕</button>
            </div>

            @if (_threadRootMessage is not null)
            {
                <div class="thread-root-quote">
                    <span class="msg-author">@_threadRootMessage.Author</span>
                    <span class="msg-time">@FormatRelativeTime(_threadRootMessage.SentAt)</span>
                    <div class="msg-content">@_threadRootMessage.Content</div>
                </div>
            }

            <div class="thread-messages">
                @if (_threadMessages is not null)
                {
                    @foreach (var reply in _threadMessages.Skip(1))
                    {
                        <div class="message-bubble thread-reply">
                            <div class="message-meta">
                                <span class="msg-author">@reply.Author</span>
                                <span class="msg-time">@FormatRelativeTime(reply.SentAt)</span>
                            </div>
                            <div class="msg-content">@reply.Content</div>
                        </div>
                    }
                }
            </div>

            <div class="message-input-area">
                <textarea class="message-input" rows="2" placeholder="Reply in thread…"
                          @bind="_threadReplyText" @bind:event="oninput"
                          @onkeydown="OnThreadKeyDown" />
                <button class="send-btn" @onclick="SendThreadReplyAsync"
                        disabled="@string.IsNullOrWhiteSpace(_threadReplyText)">
                    Reply
                </button>
            </div>
        </aside>
    }
</div>

@code {
    private const int PageSize = 50;
    private static readonly string[] _commonEmojis = { "👍", "❤️", "😂", "🎉", "🚀", "👀" };

    private List<Channel>? _channels;
    private int _activeChannelId;
    private Channel? _activeChannel;

    private List<Message>? _messages;
    private List<Message>? _allChannelMessages; // includes replies, for counting
    private int _skip;
    private bool _loadingOlder;
    private bool _hasMoreOlder = true;

    private string _newMessageText = "";
    private int? _hoveredMessageId;
    private int? _emojiPickerMessageId;

    // Thread state
    private bool _threadOpen;
    private int? _threadRootId;
    private Message? _threadRootMessage;
    private List<Message>? _threadMessages;
    private string _threadReplyText = "";

    private ElementReference _messageListRef;

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
            await SelectChannelAsync(_channels[0].Id);
    }

    private async Task SelectChannelAsync(int channelId)
    {
        _activeChannelId = channelId;
        _activeChannel = _channels?.FirstOrDefault(c => c.Id == channelId);
        _skip = 0;
        _hasMoreOlder = true;
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _skip = _messages.Count;

        await ChatService.MarkChannelReadAsync(channelId);
        _channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (_loadingOlder || !_hasMoreOlder) return;
        _loadingOlder = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_activeChannelId, _skip, PageSize);
        if (older.Count == 0)
        {
            _hasMoreOlder = false;
        }
        else
        {
            _messages = older.Concat(_messages ?? new()).ToList();
            _skip += older.Count;
        }
        _loadingOlder = false;
    }

    private async Task OnMessageListScroll()
    {
        // Scroll-to-top triggers loading older messages
        await LoadOlderMessagesAsync();
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(_newMessageText)) return;

        var sent = await ChatService.SendMessageAsync(_activeChannelId, _newMessageText.Trim(), null);
        _messages ??= new();
        _messages.Add(sent);
        _newMessageText = "";
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendMessageAsync();
        }
    }

    private async Task OpenThreadAsync(int rootMessageId)
    {
        _threadRootId = rootMessageId;
        _threadMessages = await ChatService.GetThreadAsync(rootMessageId);
        _threadRootMessage = _threadMessages.FirstOrDefault();
        _threadOpen = true;
        _emojiPickerMessageId = null;
    }

    private void CloseThread()
    {
        _threadOpen = false;
        _threadRootId = null;
        _threadMessages = null;
        _threadRootMessage = null;
        _threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(_threadReplyText) || _threadRootId == null) return;

        var reply = await ChatService.SendMessageAsync(_activeChannelId, _threadReplyText.Trim(), _threadRootId);
        _threadMessages ??= new();
        _threadMessages.Add(reply);
        _threadReplyText = "";
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await SendThreadReplyAsync();
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        _emojiPickerMessageId = _emojiPickerMessageId == messageId ? null : messageId;
    }

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        _emojiPickerMessageId = null;

        // Refresh messages to show updated reactions
        _messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _skip == 0 ? PageSize : _skip);

        // Refresh thread if open
        if (_threadOpen && _threadRootId.HasValue)
            _threadMessages = await ChatService.GetThreadAsync(_threadRootId.Value);
    }

    private int GetReplyCount(int rootMessageId)
    {
        // Fetch thread info synchronously from cached data when available
        return _threadMessages is not null && _threadRootId == rootMessageId
            ? _threadMessages.Count - 1
            : _allChannelMessages?.Count(m => m.ReplyToId == rootMessageId) ?? 0;
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return sentAt.ToString("MMM d, h:mm tt");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length > 30 ? desc[..30] + "…" : desc;
    }
}
